import type { BattleAction } from './types.ts';

export interface BattleRoundCommand {
  side: 'player' | 'enemy';
  partyIndex: number;
  action: BattleAction;
  priority: number;
  speed: number;
  /** Stable random tie-break value generated by the battle RNG. */
  tieBreak: number;
}

export interface BossRoundPlan {
  /** Exactly one command for each submitted allied action and one enemy command. */
  commands: BattleRoundCommand[];
}

/**
 * Orders a boss round without resolving it.
 *
 * The caller supplies one action per deployed ally and exactly one enemy action.
 * Priority wins first, then effective speed, then the RNG-provided tie-break.
 * This pure planner deliberately does not mutate battle state.
 */
export function planBossRound(
  alliedCommands: readonly BattleRoundCommand[],
  enemyCommand: BattleRoundCommand
): BossRoundPlan {
  if (alliedCommands.length < 1 || alliedCommands.length > 3) {
    throw new RangeError('A boss round requires between one and three allied actions.');
  }
  if (enemyCommand.side !== 'enemy') {
    throw new TypeError('The boss round must contain exactly one enemy command.');
  }

  const seenPartyIndices = new Set<number>();
  for (const command of alliedCommands) {
    if (command.side !== 'player') {
      throw new TypeError('Allied commands must belong to the player side.');
    }
    if (seenPartyIndices.has(command.partyIndex)) {
      throw new TypeError('Each deployed ally may submit only one action per round.');
    }
    seenPartyIndices.add(command.partyIndex);
  }

  const commands = [...alliedCommands, enemyCommand];
  commands.sort((a, b) => {
    if (a.priority !== b.priority) return b.priority - a.priority;
    if (a.speed !== b.speed) return b.speed - a.speed;
    return a.tieBreak - b.tieBreak;
  });

  return { commands };
}
